messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Humanoid Cycle</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #111; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x222222);
        scene.fog = new THREE.Fog(0x222222, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 2, 6); // Side-on view
        camera.lookAt(0, 1, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const hemiLight = new THREE.HemisphereLight(0xffffff, 0x444444, 1);
        scene.add(hemiLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
        dirLight.position.set(5, 10, 5);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // --- Environment ---
        // Treadmill
        const beltGeo = new THREE.BoxGeometry(4, 0.2, 1.5);
        const beltMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const belt = new THREE.Mesh(beltGeo, beltMat);
        belt.position.y = -0.1;
        belt.receiveShadow = true;
        scene.add(belt);

        const frameGeo = new THREE.BoxGeometry(0.2, 0.4, 1.5);
        const frameMat = new THREE.MeshStandardMaterial({ color: 0x555555 });

        const leftFrame = new THREE.Mesh(frameGeo, frameMat);
        leftFrame.position.set(-2.1, 0, 0);
        leftFrame.castShadow = true;
        scene.add(leftFrame);

        const rightFrame = new THREE.Mesh(frameGeo, frameMat);
        rightFrame.position.set(2.1, 0, 0);
        rightFrame.castShadow = true;
        scene.add(rightFrame);

        // --- Character Construction ---
        const skinColor = 0xe0ac69;
        const shirtColor = 0x3366ff;
        const pantsColor = 0x222222;

        const skinMat = new THREE.MeshStandardMaterial({ color: skinColor, flatShading: true });
        const shirtMat = new THREE.MeshStandardMaterial({ color: shirtColor, flatShading: true });
        const pantsMat = new THREE.MeshStandardMaterial({ color: pantsColor, flatShading: true });

        // Hips (Root of the body)
        const hips = new THREE.Group();
        hips.position.y = 1.0;
        scene.add(hips);

        // Torso
        const torso = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.5, 0.25), shirtMat);
        torso.position.y = 0.25;
        torso.castShadow = true;
        hips.add(torso);

        // Head
        const head = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.3, 0.25), skinMat);
        head.position.y = 0.6; // 0.5 (torso top) + 0.1 (half head)
        head.castShadow = true;
        torso.add(head);

        // Limb Helper
        function createLimb(w, h, d, material, pivotY) {
            const group = new THREE.Group();
            group.position.y = pivotY;

            const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
            mesh.position.y = -h / 2; // Pivot at top
            mesh.castShadow = true;

            group.add(mesh);
            return group;
        }

        // Arms
        const leftUpperArm = createLimb(0.12, 0.35, 0.12, shirtMat, 0.4);
        torso.add(leftUpperArm);

        const rightUpperArm = createLimb(0.12, 0.35, 0.12, shirtMat, 0.4);
        torso.add(rightUpperArm);

        // Legs
        const leftUpperLeg = createLimb(0.16, 0.4, 0.16, pantsMat, -0.25); // -0.25 relative to hips
        hips.add(leftUpperLeg);

        const rightUpperLeg = createLimb(0.16, 0.4, 0.16, pantsMat, -0.25);
        hips.add(rightUpperLeg);


        // --- Animation Logic ---

        // 10s Cycle: 0-2 (Idle), 2-5 (Walk), 5-8 (Run), 8-10 (Idle)
        const CYCLE_DURATION = 10; 

        function getAnimationParams(t) {
            // t is 0 to 10
            if (t < 2 || t > 8) {
                // Idle
                return {
                    type: 'idle',
                    time: 0, // dummy
                    speed: 0,
                    swing: 0,
                    lean: 0,
                    bounce: 0
                };
            } else if (t < 5) {
                // Walk (3s)
                // 0 to 1 normalized time
                const norm = (t - 2) / 3; 
                return {
                    type: 'walk',
                    time: norm * Math.PI * 2,
                    speed: 1,
                    swing: 0.4, // ~23 degrees
                    lean: 0,
                    bounce: 0.02
                };
            } else if (t < 8) {
                // Run (3s)
                // 0 to 1 normalized time
                const norm = (t - 5) / 3;
                return {
                    type: 'run',
                    time: norm * Math.PI * 4, // 2 full cycles in 3 seconds
                    speed: 2,
                    swing: 0.9, // ~50 degrees
                    lean: 0.15, // 8 degrees
                    bounce: 0.08
                };
            }
            return { type: 'idle', time: 0, speed: 0, swing: 0, lean: 0, bounce: 0 };
        }

        function animateModel(params) {
            if (params.type === 'idle') {
                // Reset
                leftUpperLeg.rotation.x = 0;
                rightUpperLeg.rotation.x = 0;
                leftUpperArm.rotation.x = 0;
                rightUpperArm.rotation.x = 0;
                torso.rotation.x = 0;
                hips.position.y = 1.0;
                return;
            }

            // Sine wave for oscillation
            const sin = Math.sin(params.time);
            const sin2 = Math.sin(params.time + Math.PI); // Opposite limb

            // Apply Lean
            torso.rotation.x = -params.lean;

            // Apply Bounce (vertical)
            // Bounce is 2x frequency of steps (up-down per step, but step is full cycle)
            // Actually, for running, bounce is 2x the stride freq. For walk, 2x.
            const bounceFreq = params.type === 'run' ? 2 : 2;
            const bounceVal = Math.abs(Math.sin(params.time * bounceFreq)); 
            hips.position.y = 1.0 + (bounceVal * params.bounce);

            // Apply Limb Swing
            // Left Leg
            leftUpperLeg.rotation.x = sin * params.swing;
            // Right Leg
            rightUpperLeg.rotation.x = sin2 * params.swing;

            // Arms (Opposite to legs)
            // Left Arm (matches Right Leg)
            leftUpperArm.rotation.x = sin2 * params.swing * 0.8; // Arms swing slightly less
            // Right Arm (matches Left Leg)
            rightUpperArm.rotation.x = sin * params.swing * 0.8;
        }


        // --- Main Loop ---
        const clock = new THREE.Clock();

        function render() {
            requestAnimationFrame(render);

            const elapsed = clock.getElapsedTime();
            const cycleTime = elapsed % CYCLE_DURATION;

            const params = getAnimationParams(cycleTime);
            animateModel(params);

            // Treadmill visual effect (simple rotation of a texture or just static for low poly)
            // Let's just move the belt texture if we had one, but we don't. 
            // We can slightly pulse the belt color to simulate movement if desired, 
            // but the static belt is fine for the "low poly" aesthetic.

            renderer.render(scene, camera);
        }

        // Handle resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start
        render();

    </script>
</body>
</html>
```
